password_keywords := {"password", "passwd", "pwd", "pass", "secret", "auth_secret", "client_secret", "admin_password", "root_password", "user_password", "credential_password", "db_password", "database_password", "api_key", "access_key", "tls_password", "ssl_password", "cert_password"}

is_password_key(name) {
    lower_name := lower(name)
    contains(lower_name, password_keywords[_])
}

is_empty_password_value(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

check_empty_in_value(value) {
    is_empty_password_value(value)
} else {
    value.ir_type == "Array"
    [a | a := value.value[_]] == []
} else {
    value.ir_type == "Hash"
    [k | k := value.value[_]] == []
} else {
    value.ir_type == "AddArgs"
    [a | a := value.value[_]] == []
}

check_nested_empty(value) {
    is_empty_password_value(value)
} else {
    value.ir_type == "Array"
    some v in value.value
    check_nested_empty(v)
} else {
    value.ir_type == "Hash"
    some v in value.value
    v.ir_type == "KeyValue"
    is_password_key(v.name)
    check_nested_empty(v.value)
} else {
    value.ir_type == "Hash"
    some v in value.value
    check_nested_empty(v)
} else {
    value.ir_type == "AddArgs"
    some v in value.value
    check_nested_empty(v)
}

